	const first = pcSpeedOf(A) * 10 + (A.melee || 0) + (A.archery || 0) + kcRng() >= pcSpeedOf(B) * 10 + (B.melee || 0) + (B.archery || 0) + kcRng() ? A : B, second = first === A ? B : A;
