					const dealt = pcTakeHit(turnContext, foe, dmg, narrative, actor.name, "free strike");
					if (dealt) narrate(narrative, `  ${actor.name}'s free strike lands for ${dealt} damage! (${foe.name} HP ${Math.max(0, Math.round(foe.hp))})`);
