	const basicRate = { ...KC_BASIC_EXPLORE }[prov.terrain] || 15;
	const explorerSkill = Math.min(5, effStat(turnContext, c, "explorer"));
	const scoutBonus = 1;
	const loreMult = charMinor(turnContext, c, "trailblazer") ? 1.05 : 1;
