		const pupilNote = pupils.length ? ` — trains ${pupils.map((t) => `${t.name} (${SKILL_LABELS[skill] || skill} ${snapLvl(t)})`).join(" & ")} in ${SKILL_LABELS[skill] || skill}` : "";
