	const maxTurns = cfg.maxTurns || 12;
	const sizemap = {
		p2: {
			cols: 8,
			rows: 5
		},
		p3: {
			cols: 8,
			rows: 7
		},
		p4: {
			cols: 9,
			rows: 7
		},
		p5: {
			cols: 12,
			rows: 7
		},
		p6: {
			cols: 15,
			rows: 7
		},
		p7: {
			cols: 16,
			rows: 7
		},
		p8: {
			cols: 17,
			rows: 8
		},
		p9: {
			cols: 16,
			rows: 11
		},
		p10: {
			cols: 16,
			rows: 11
		}
	};
	const sz = sizemap[mapSize] || sizemap.p5;
